import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';

import { AppRoutingModule } from './app-routing.module';
import { AppComponent } from './app.component';
import { FooterComponent } from './component/footer/footer.component';
import { HeaderComponent } from './component/header/header.component';
import { NavComponent } from './component/nav/nav.component';
import { MainComponent } from './component/main/main.component';
import { HttpClientModule } from "@angular/common/http";
import { CharacterListComponent } from './character/view/character-list/character-list.component';
import { WeaponService } from '../app/weapon/service/weapon.service';
import { CharacterViewComponent } from './character/view/character-view/character-view.component';
import { WeaponEditComponent } from './character/view/weapon-edit/weapon-edit.component';
import { FormsModule } from "@angular/forms";

/**
 * Application main module.
 */
@NgModule({
  declarations: [
    AppComponent,
    FooterComponent,
    HeaderComponent,
    NavComponent,
    MainComponent,
    CharacterListComponent,
    CharacterViewComponent,
    CharacterEditComponent
  ],
  imports: [
    BrowserModule,
    AppRoutingModule,
    FormsModule,
    HttpClientModule
  ],
  providers: [
    CharacterService,
  ],
  bootstrap: [
    AppComponent
  ]
})
export class AppModule {

}
